rules.suggestion:
1. 禁止将密码、Token等敏感信息复制到系统剪贴板；2. 如必须提供复制功能，使用应用内安全的剪贴板实现，设置自动过期；3. Android上使用setClipData时标记为敏感信息（API 33+）；4. 对敏感输入框禁用长按复制功能；5. 应用进入后台时清除剪贴板中的敏感内容。

示例（Android - Kotlin）：
```kotlin
// 标记剪贴板内容为敏感信息（Android 13+）
val clipData = ClipData.newPlainText("", sensitiveText)
clipData.description.extras = PersistableBundle().apply {
    putBoolean(ClipDescription.EXTRA_IS_SENSITIVE, true)
}
clipboardManager.setPrimaryClip(clipData)

// 对密码输入框禁止复制
// XML: android:inputType="textPassword"
// 密码字段默认禁止复制到剪贴板
```

示例（iOS - Swift）：
```swift
// 密码输入框禁止复制
passwordField.isSecureTextEntry = true
// UITextField的isSecureTextEntry会自动禁止复制

// 如需要临时复制，设置过期
UIPasteboard.general.string = token
UIPasteboard.general.setItems([[UIPasteboard.typeAutomatic: token]],
    options: [.expirationDate: Date().addingTimeInterval(60)])
```

1. 在生产构建中禁用或最小化日志输出；2. 使用日志级别控制，生产环境仅允许ERROR级别以上；3. 实施日志脱敏框架，自动过滤敏感字段；4. 禁止在日志中输出凭证、Token、PII等；5. 使用代码扫描规则检测日志中的敏感模式；6. 对第三方SDK的日志输出进行审计。

示例（Android - Kotlin）：
```kotlin
// 封装安全日志工具
object SafeLogger {
    private const val TAG = "AppLogger"

    fun d(tag: String, message: String) {
        if (BuildConfig.DEBUG) {
            Log.d(tag, message)
        }
    }

    // 自动脱敏
    fun logApiRequest(request: Request) {
        val sanitized = request.toString()
            .replace(Regex("(Authorization:\s*)Bearer\\s+\\S+"), "$1***")
            .replace(Regex("(password=)[^&]+"), "$1***")
        d(TAG, sanitized)
    }
}
```

示例（iOS - Swift）：
```swift
enum LogLevel: Int {
    case debug = 0, info, warning, error
}

class Logger {
    static var level: LogLevel = .error  // 生产环境设置

    static func debug(_ message: String, file: String = #file) {
        guard level <= .debug else { return }
        // 过滤敏感模式
        let sanitized = sanitize(message)
        print("[DEBUG] \(sanitized)")
    }

    private static func sanitize(_ text: String) -> String {
        var result = text
        result = result.replacingOccurrences(
            of: "token=\\w+", with: "token=***", options: .regularExpression)
        return result
    }
}
```

1. 在应用进入后台时覆盖敏感界面（显示Logo或模糊层）；2. 使用FLAG_SECURE（Android）阻止截屏和后台截图；3. 对包含敏感信息的视图禁用截屏功能；4. 在iOS上使用UIApplication的ignoreScreenshot机制；5. 在关键界面禁用系统截屏。

示例（Android - Kotlin）：
```kotlin
class SecureActivity : AppCompatActivity() {
    override fun onPause() {
        super.onPause()
        // 进入后台时用Logo覆盖
        secureOverlay.visibility = View.VISIBLE
    }

    override fun onResume() {
        super.onResume()
        secureOverlay.visibility = View.GONE
    }
}

// 禁止截屏的Activity
class PaymentActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.setFlags(
            WindowManager.LayoutParams.FLAG_SECURE,
            WindowManager.LayoutParams.FLAG_SECURE
        )
    }
}
```

示例（iOS - Swift）：
```swift
// 在AppDelegate中监听后台切换
func applicationDidEnterBackground(_ application: UIApplication) {
    let blurView = UIVisualEffectView(effect: UIBlurEffect(style: .light))
    blurView.frame = window.rootViewController!.view.bounds
    blurView.tag = 999
    window.rootViewController!.view.addSubview(blurView)
}

func applicationWillEnterForeground(_ application: UIApplication) {
    window.rootViewController!.view.viewWithTag(999)?.removeFromSuperview()
}
```
